        visited = set()

        def dfs(v):
            stack = [v]
            while stack:
                u = stack.pop()
                if u not in visited:
                    visited.add(u)
                    for v in range(n):
                        if adj_matrix[u][v] == 1 and v not in visited:
                            stack.append(v)

